242 0%, #0d1f6c 80%, #1432a8 100%);\n  color: #f4f9ff;\n  border: 2.5px solid #ffffff;\n  border-left: 7px solid #f43252;\n  box-shadow: 6px 6px 0 rgba(8, 20, 74, 0.3);\n  transform: rotate(-0.5deg);\n}\n\n.bp-chat-narration p {\n  margin: 0;\n  font-size: calc(clamp(14px, 1.3cqi, 18.5px) * var(--bp-reading-scale, 1));\n  font-weight: 650;\n  line-height: 1.76;\n  letter-spacing: 0.025em;\n  text-align: left;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  text-wrap: pretty;\n}\n\n/* =========================================================\n   P5R Comic SNS Dialogue Row (Left NPC vs Right Player)\n   ========================================================= */\n.bp-chat-dialogue {\n  display: flex;\n  align-items: flex-start;\n  gap: clamp(18px, 2.2cqi, 30px);\n  width: 100%;\n  min-width: 0;\n  padding-top: clamp(18px, 2cqi, 28px);\n}\n\n.bp-chat-dialogue:not(.starts-group) {\n  padding-top: 0;\n  margin-top: -10px;\n}\n\n.bp-chat-dialogue.is-right {\n  flex-direction: row-reverse;\n}\n\n.bp-chat-dialogue.is-center {\n  flex-direction: column;\n  align-items: center;\n  gap: 14px;\n}\n\n/* =========================================================\n   Iconic P5R Pop-Out Head-Focused Comic Portrait Slot\n   ========================================================= */\n.bp-chat-avatar-slot {\n  position: relative;\n  flex: 0 0 var(--p5-portrait-w);\n  width: var(--p5-portrait-w);\n  min-height: 1px;\n  z-index: 3;\n}\n\n.bp-chat-avatar-trigger {\n  appearance: none;\n  position: relative;\n  display: block;\n  width: 100%;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  cursor: pointer;\n  transition: transform 170ms cubic-bezier(0.2, 0.8, 0.2, 1);\n  -webkit-tap-highlight-color: transparent;\n}\n\n.bp-chat-row.is-odd-tilt .bp-chat-avatar-trigger {\n  transform: rotate(1.6deg);\n}\n\n.bp-chat-row.is-odd-tilt .bp-chat-dialogue.is-right .bp-chat-avatar-trigger {\n  transform: rotate(-1.6deg);\n}\n\n.bp-chat-avatar-trigger:hover {\n  transform: scale(1.05) translateY(-4px) !important;\n}\n\n.bp-chat-avatar-trigger:focus-visible {\n  outline: 2.5px solid #24e2f8;\n  outline-offset: 4px;\n}\n\n.bp-chat-cutin-frame {\n  position: relative;\n  display: block;\n  width: 100%;\n  aspect-ratio: 200 / 176;\n  --p5-port-ink: #040712;\n  --p5-port-fill: #70c8fb;\n  --p5-port-shadow: rgba(6, 13, 44, 0.24);\n}\n\n.bp-chat-dialogue.is-right .bp-chat-cutin-frame {\n  --p5-port-fill: #ff5678;\n  --p5-port-shadow: rgba(244, 50, 82, 0.28);\n}\n\n.bp-chat-row.is-active .bp-chat-cutin-frame {\n  --p5-port-shadow: rgba(36, 226, 248, 0.48);\n}\n\n/* Open headroom above the slanted black rim; tightly aligned with inner white collar along bottom & left slope */\n.bp-chat-cutin-clip {\n  position: absolute;\n  inset: 0;\n  z-index: 2;\n  display: grid;\n  place-items: center;\n  clip-path: polygon(-12% -26%, 112% -26%, 112% 22%, 102% 52%, 87.5% 78%, 33.5% 87.8%, 14.5% 32%, -12% 20%);\n  pointer-events: none;\n}\n\n.bp-chat-cutin-clip.is-mirrored {\n  clip-path: polygon(-12% -26%, 112% -26%, 112% 20%, 85.5% 32%, 66.5% 87.8%, 12.5% 78%, -2% 52%, -12% 22%);\n}\n\n.bp-chat-avatar-image {\n  position: absolute;\n  left: 55%;\n  display: block;\n  max-width: none;\n  transform: translateX(-50%);\n  filter: drop-shadow(0 3px 0 rgba(4, 7, 18, 0.22));\n  animation: p5-face-in 160ms ease-out;\n}\n\n.bp-chat-cutin-clip.is-mirrored .bp-chat-avatar-image {\n  left: 45%;\n}\n\n/* Chibi / square avatar: zoom onto head & shoulders so crown bursts boldly above the black top edge */\n.bp-chat-avatar-image.is-avatar {\n  top: -7%;\n  width: 120%;\n  height: auto;\n  object-fit: contain;\n  object-position: center top;\n}\n\n/* Full-body portrait: tight head & collar close-up bursting cleanly above top edge */\n.bp-chat-avatar-image.is-portrait {\n  top: -7%;\n  width: 148%;\n  height: auto;\n  object-fit: contain;\n  object-position: center top;\n}\n\n.bp-chat-avatar-fallback {\n  position: relative;\n  top: 10%;\n  left: 4%;\n  color: #040712;\n  font-family: var(--bp-title-font, sans-serif);\n  font-size: clamp(30px, 3.8cqi, 48px);\n  font-weight: 950;\n  text-shadow: 2px 2px 0 #ffffff;\n}\n\n.bp-chat-cutin-clip.is-mirrored .bp-chat-avatar-fallback {\n  left: -4%;\n}\n\n@keyframes p5-face-in {\n  from {\n    opacity: 0;\n  }\n  to {\n    opacity: 1;\n  }\n}\n\n/* =========================================================\n   Message Stack: Taped Comic Nameplate + Jagged Solid Bubble\n   ========================================================= */\n.bp-chat-message-stack {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  flex: 1 1 auto;\n  max-width: min(74%, calc(100% - var(--p5-portrait-w) - 20px));\n  min-width: 0;\n  padding-top: clamp(20px, 2.2cqi, 32px);\n}\n\n.bp-chat-dialogue:not(.starts-group) .bp-chat-message-stack {\n  padding-top: 0;\n}\n.bp-chat-dialogue.is-right .bp-chat-message-stack {\n  align-items: flex-end;\n}\n\n.bp-chat-dialogue.is-center .bp-chat-message-stack {\n  align-items: center;\n  flex-basis: auto;\n  width: min(86%, 800px);\n  max-width: 100%;\n}\n\n.bp-chat-speaker-line {\n  position: relative;\n  z-index: 4;\n  display: inline-flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 0;\n  margin-bottom: -10px;\n  margin-left: 14px;\n  transform: rotate(-1.5deg);\n}\n\n.bp-chat-dialogue.is-right .bp-chat-speaker-line {\n  flex-direction: row-reverse;\n  margin-left: 0;\n  margin-right: 14px;\n  transform: rotate(1.5deg);\n}\n\n.bp-chat-speaker-name {\n  display: inline-flex;\n  align-items: center;\n  padding: 4px 16px 4px 13px;\n  background: #ffffff;\n  color: #08144a;\n  border: 2.5px solid #08144a;\n  box-shadow: 4px 3px 0 #f43252;\n  transform: skewX(-10deg);\n  font-family: var(--bp-title-font, 'Microsoft YaHei', sans-serif);\n  font-size: clamp(14.5px, 1.4cqi, 20px);\n  font-weight: 950;\n  line-height: 1.15;\n  letter-spacing: 0.05em;\n}\n\n.bp-chat-dialogue.is-right .bp-chat-speaker-name {\n  background: #08144a;\n  color: #ffffff;\n  border-color: #ffffff;\n  box-shadow: -4px 3px 0 #24e2f8;\n}\n\n.bp-chat-speaker-affiliation {\n  display: inline-flex;\n  align-items: center;\n  margin-left: 7px;\n  padding: 3px 10px;\n  background: #163ee8;\n  color: #eaf9ff;\n  border: 1.8px solid #ffffff;\n  transform: skewX(-10deg);\n  font-size: clamp(10px, 0.9cqi, 13px);\n  font-weight: 850;\n  line-height: 1.15;\n  letter-spacing: 0.04em;\n}\n\n.bp-chat-dialogue.is-right .bp-chat-speaker-affiliation {\n  margin-left: 0;\n  margin-right: 7px;\n}\n\n/* Jagged Comic Speech Bubble Shell */\n.bp-chat-bubble-shell {\n  position: relative;\n  isolation: isolate;\n  width: 100%;\n  min-width: 180px;\n  transition: transform 160ms cubic-bezier(0.2, 0.8, 0.2, 1);\n\n  /* NPC Default: Solid Deep Academy Indigo + Thick Pure White Collar + Crimson Corner */\n  --p5-bub-fill: #08144a;\n  --p5-bub-stroke: #ffffff;\n  --p5-bub-shadow: rgba(22, 62, 232, 0.36);\n  --p5-bub-accent: #f43252;\n  --p5-bub-inner: rgba(36, 226, 248, 0.5);\n  --p5-bub-sheen: rgba(255, 255, 255, 0.06);\n}\n\n.bp-chat-dialogue.is-right .bp-chat-bubble-shell {\n  /* Player Default: High-Contrast Inverted Pure White + Thick Indigo Ink Collar + Electric Cyan Corner */\n  --p5-bub-fill: #ffffff;\n  --p5-bub-stroke: #08144a;\n  --p5-bub-shadow: rgba(244, 50, 82, 0.42);\n  --p5-bub-accent: #24e2f8;\n  --p5-bub-inner: rgba(22, 62, 232, 0.22);\n  --p5-bub-sheen: rgba(36, 226, 248, 0.09);\n}\n\n.bp-chat-row:hover .bp-chat-bubble-shell {\n  transform: translate(3px, -2px);\n  --p5-bub-shadow: rgba(36, 226, 248, 0.68);\n}\n\n.bp-chat-row:hover .bp-chat-dialogue.is-right .bp-chat-bubble-shell {\n  transform: translate(-3px, -2px);\n  --p5-bub-shadow: rgba(22, 62, 232, 0.62);\n}\n\n.bp-chat-row.is-active .bp-chat-bubble-shell {\n  --p5-bub-stroke: #24e2f8;\n  --p5-bub-shadow: rgba(244, 50, 82, 0.72);\n}\n\n.bp-chat-row.is-active .bp-chat-dialogue.is-right .bp-chat-bubble-shell {\n  --p5-bub-stroke: #f43252;\n  --p5-bub-shadow: rgba(36, 226, 248, 0.75);\n}\n\n.bp-chat-bubble {\n  margin: 0;\n  padding: clamp(20px, 1.9cqi, 28px) clamp(24px, 2.3cqi, 34px) clamp(16px, 1.6cqi, 22px);\n  color: #f4faff;\n  font-size: calc(clamp(15px, 1.35cqi, 20px) * var(--bp-reading-scale, 1));\n  font-weight: 700;\n  line-height: 1.74;\n  letter-spacing: 0.025em;\n  text-align: left;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  text-wrap: pretty;\n}\n\n.bp-chat-dialogue:not(.starts-group) .bp-chat-bubble {\n  padding-top: clamp(13px, 1.25cqi, 18px);\n}\n\n.bp-chat-dialogue.is-right .bp-chat-bubble {\n  color: #08144a;\n}\n\n/* =========================================================\n   Responsive / Mobile Tuning\n   ========================================================= */\n.bp-chat-thread.is-mobile .bp-chat-dialogue {\n  gap: 14px;\n  padding-top: 12px;\n}\n\n.bp-chat-thread.is-mobile .bp-chat-message-stack {\n  max-width: calc(100% - var(--p5-portrait-w) - 14px);\n}\n\n.bp-chat-thread.is-mobile .bp-chat-speaker-name {\n  font-size: 13px;\n  padding: 3px 10px 3px 9px;\n}\n\n.bp-chat-thread.is-mobile .bp-chat-speaker-affiliation {\n  font-size: 9.5px;\n  padding: 2px 7px;\n}\n\n.bp-chat-thread.is-mobile .bp-chat-bubble {\n  padding: 15px 15px 12px;\n  font-size: calc(14px * var(--bp-reading-scale, 1));\n  line-height: 1.66;\n}\n\n.bp-chat-thread.is-mobile .bp-chat-narration {\n  max-width: 98%;\n  padding: 12px 14px;\n}\n\n@container bp-host (max-width: 900px) {\n  .bp-chat-thread.is-desktop .bp-chat-message-stack {\n    max-width: calc(100% - var(--p5-portrait-w) - 20px);\n  }\n}\n\n@container bp-host (max-width: 560px) {\n  .bp-chat-thread .bp-chat-dialogue {\n    gap: 12px;\n    padding-top: 12px;\n  }\n  .bp-chat-thread .bp-chat-message-stack {\n    max-width: calc(100% - var(--p5-portrait-w) - 12px);\n  }\n  .bp-chat-thread .bp-chat-speaker-line {\n    margin-left: 8px;\n    margin-bottom: -8px;\n  }\n  .bp-chat-thread .bp-chat-dialogue.is-right .bp-chat-speaker-line {\n    margin-left: 0;\n    margin-right: 8px;\n  }\n  .bp-chat-thread .bp-chat-speaker-name {\n    font-size: 12.5px;\n    padding: 3px 10px 3px 8px;\n  }\n  .bp-chat-thread .bp-chat-bubble {\n    padding: 14px 14px 11px;\n    font-size: calc(13.5px * var(--bp-reading-scale, 1));\n  }\n  .bp-chat-thread .bp-chat-narration {\n    max-width: 98%;\n    padding: 11px 14px;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .bp-chat-row,\n  .bp-chat-avatar-trigger,\n  .bp-chat-bubble-shell,\n  .bp-chat-avatar-image {\n    animation: none !important;\n    transition: none !important;\n  }\n}\n"],"sourceRoot":""}]);
